/* inicializacion del puerto
   dir: direccion de los pines del puerto */
void ini_PORTB(int dir)
{
    TRISB = dir;
}

/* funcion que devuelve los datos del puerto B */
int get_PORTB()
{
    return (PORTB);
}

/* funcion modifica los datos del puerto B */
void set_PORTB(int datos)
{
    PORTB = datos;
}

/* A evitar: dos lecturas-modificaciones-escrituras seguidas del puerto */
set_PORTB(get_PORTB() & ~0x1000);   // enciende D9 (RB12)
set_PORTB(get_PORTB() & ~0x2000);   // enciende D8 (RB13)

/* Bien (solución 2): se modifica una variable y se escribe una sola vez */
int salida = get_PORTB();
salida &= ~0x1000;                  // D9 (RB12)
salida &= ~0x2000;                  // D8 (RB13)
set_PORTB(salida);

