int get_medida(int detector);   // está en ensamblador (get_medida.s)

//---------------- DRIVER del detector
// Variables globales del driver: el valor anterior de cada detector,
// un byte por detector: 0x900 (detector 1), 0x901 (2) y 0x902 (3).

/* inicializa_driver_detectores
   Qué hace:   configura RB0-RB2 como entradas digitales y guarda el
               estado actual de cada detector como «valor anterior».
   Parámetros: ninguno.
   Devuelve:   nada.                                                  */
void inicializa_driver_detectores(void)
{
    unsigned char *anterior = (unsigned char *) 0x900;
    unsigned int actual;

    AD1PCFGL |= 0x001C;      // RB0-RB2 (AN2-AN4) como pines digitales
    TRISB |= 0x0007;         // RB0-RB2 como entradas (no toca el resto)
    asm("nop");              // un ciclo entre cambiar TRISB y leer el puerto
    actual = PORTB;          // una sola lectura del puerto
    anterior[0] = actual & 0x0001;   // detector 1 (RB0)
    anterior[1] = actual & 0x0002;   // detector 2 (RB1)
    anterior[2] = actual & 0x0004;   // detector 3 (RB2)
}

/* get_medidas
   Qué hace:   barre los tres detectores llamando a get_medida.
   Parámetros: ninguno.
   Devuelve:   un entero con un bit por detector: bit 0 = detector 1,
               bit 1 = detector 2 y bit 2 = detector 3
               (1 = flanco de subida, hay pájaro; 0 = no hay pájaro).  */
int get_medidas(void)
{
    int detector;
    int medidas = 0;

    for (detector = 1; detector <= 3; detector++) {
        if (get_medida(detector))
            medidas |= 1 << (detector - 1);
    }
    return medidas;
}
